import type { Locale } from '$lib/i18n'
import MarkdownIt from 'markdown-it'
import versions from './terms.json'

export type LegalKind = 'privacy' | 'terms' | 'support'

export interface TermsVersion {
  version: number
  path: string
  sha256: string
}

export interface LegalDocument {
  title: string
  html: string
  sections: { id: string; title: string }[]
  /** Language of the text shown, which falls back to English. */
  locale: Locale
}

/** Published terms, oldest first, as generated by scripts/terms-digest.mjs. */
export const termsVersions: readonly TermsVersion[] = versions
export const currentTerms = termsVersions[termsVersions.length - 1]!

// Translations, and the English privacy policy and support page. The English
// terms are not here: the page fetches the published file, so readers see the
// exact bytes whose digest dmsg_commerce records.
const documents = import.meta.glob<string>('./**/*.md', {
  query: '?raw',
  import: 'default'
})

const md = new MarkdownIt({ html: false, linkify: true })
md.linkify.set({ fuzzyLink: false, fuzzyEmail: false })
const linkOpen =
  md.renderer.rules['link_open'] ??
  ((tokens, idx, options, _env, self) => self.renderToken(tokens, idx, options))
// The terms spell out absolute dmsg.net links; keep them on the current site.
md.renderer.rules['link_open'] = (tokens, idx, options, env, self) => {
  const token = tokens[idx]!
  const href = String(token.attrGet('href') ?? '')
  if (href.startsWith('https://dmsg.net/')) {
    token.attrSet('href', href.slice('https://dmsg.net'.length))
  } else if (/^https?:\/\//.test(href)) {
    token.attrSet('target', '_blank')
    token.attrSet('rel', 'noopener noreferrer')
  }
  return linkOpen(tokens, idx, options, env, self)
}

/** Lifts the first heading into the title and gives sections language-neutral anchors. */
export function renderDocument(source: string, locale: Locale): LegalDocument {
  const tokens = md.parse(source, {})
  // heading_open, inline and heading_close of the title.
  const h1 = tokens.findIndex(
    (t) => t.type === 'heading_open' && t.tag === 'h1'
  )
  const title = h1 < 0 ? '' : (tokens[h1 + 1]?.content ?? '')
  const body = h1 < 0 ? tokens : tokens.toSpliced(h1, 3)
  const sections: LegalDocument['sections'] = []
  body.forEach((token, i) => {
    if (token.type === 'heading_open' && token.tag === 'h2') {
      const id = `section-${sections.length + 1}`
      token.attrSet('id', id)
      sections.push({ id, title: body[i + 1]?.content ?? '' })
    }
  })
  return {
    title,
    html: md.renderer.render(body, md.options, {}),
    sections,
    locale
  }
}

export async function loadLegalDocument(
  kind: LegalKind,
  locale: Locale
): Promise<LegalDocument> {
  if (kind === 'terms') {
    const translation =
      documents[`./terms/v${currentTerms.version}/${locale}.md`]
    if (locale !== 'en' && translation)
      return renderDocument(await translation(), locale)
    const response = await fetch(currentTerms.path)
    if (!response.ok)
      throw new Error(`${currentTerms.path}: ${response.status}`)
    return renderDocument(await response.text(), 'en')
  }
  const localized = documents[`./${kind}/${locale}.md`]
  return localized
    ? renderDocument(await localized(), locale)
    : renderDocument(await documents[`./${kind}/en.md`]!(), 'en')
}
